    "source": "\"\"\"Kahn's topological sort. Returns [status, *order]: status 1 = acyclic (order has n nodes), 0 = cycle (order = nodes processed before it blocked).\"\"\"\n\n\ndef topo_sort(n: int, edges: list[int]) -> list[int]:\n    adj: list[list[int]] = [[] for _ in range(n)]\n    indeg = [0] * n\n    for i in range(0, len(edges) - 1, 2):\n        adj[edges[i]].append(edges[i + 1])\n        indeg[edges[i + 1]] += 1\n    queue = [v for v in range(n) if indeg[v] == 0]\n    order: list[int] = []\n    head = 0\n    while head < len(queue):\n        u = queue[head]\n        head += 1\n        order.append(u)\n        for v in adj[u]:\n            indeg[v] -= 1\n            if indeg[v] == 0:\n                queue.append(v)\n    return [1 if len(order) == n else 0] + order\n",
