    "source": "import java.util.ArrayList;\n\n/** Kahn's topological sort. Returns [status, order...]: status 1 = acyclic (order has n nodes), 0 = cycle (order = nodes processed before it blocked). */\npublic class Topo {\n    static long[] topoSort(long nn, long[] edges) {\n        int n = (int) nn;\n        ArrayList<ArrayList<Integer>> adj = new ArrayList<>();\n        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());\n        int[] indeg = new int[n];\n        for (int i = 0; i + 1 < edges.length; i += 2) {\n            adj.get((int) edges[i]).add((int) edges[i + 1]);\n            indeg[(int) edges[i + 1]]++;\n        }\n        int[] queue = new int[n];\n        int tail = 0;\n        for (int v = 0; v < n; v++) if (indeg[v] == 0) queue[tail++] = v;\n        long[] res = new long[n + 1];\n        int cnt = 0;\n        for (int head = 0; head < tail; head++) {\n            int u = queue[head];\n            res[1 + cnt++] = u;\n            for (int v : adj.get(u)) {\n                indeg[v]--;\n                if (indeg[v] == 0) queue[tail++] = v;\n            }\n        }\n        res[0] = cnt == n ? 1 : 0;\n        return java.util.Arrays.copyOf(res, cnt + 1);\n    }\n}\n",
