    "source": "// Kahn's topological sort. Returns [status, order...]: status 1 = acyclic (order has n nodes), 0 = cycle (order = nodes processed before it blocked).\npub fn topo_sort(n: i64, edges: &[i64]) -> Vec<i64> {\n    let n = n as usize;\n    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); n];\n    let mut indeg = vec![0usize; n];\n    for e in edges.chunks_exact(2) {\n        adj[e[0] as usize].push(e[1] as usize);\n        indeg[e[1] as usize] += 1;\n    }\n    let mut queue: Vec<usize> = (0..n).filter(|&v| indeg[v] == 0).collect();\n    let mut order: Vec<i64> = Vec::new();\n    let mut head = 0;\n    while head < queue.len() {\n        let u = queue[head];\n        head += 1;\n        order.push(u as i64);\n        for k in 0..adj[u].len() {\n            let v = adj[u][k];\n            indeg[v] -= 1;\n            if indeg[v] == 0 { queue.push(v); }\n        }\n    }\n    let mut res = vec![if order.len() == n { 1 } else { 0 }];\n    res.extend(order);\n    res\n}\n",
