    "source": "package main\n\n// Kahn's topological sort. Returns [status, order...]: status 1 = acyclic (order has n nodes), 0 = cycle (order = nodes processed before it blocked).\nfunc TopoSort(nn int64, edges []int64) []int64 {\n\tn := int(nn)\n\tadj := make([][]int, n)\n\tindeg := make([]int, n)\n\tfor i := 0; i+1 < len(edges); i += 2 {\n\t\tadj[edges[i]] = append(adj[edges[i]], int(edges[i+1]))\n\t\tindeg[edges[i+1]]++\n\t}\n\tqueue := []int{}\n\tfor v := 0; v < n; v++ { if indeg[v] == 0 { queue = append(queue, v) } }\n\torder := []int64{}\n\tfor head := 0; head < len(queue); head++ {\n\t\tu := queue[head]\n\t\torder = append(order, int64(u))\n\t\tfor _, v := range adj[u] {\n\t\t\tindeg[v]--\n\t\t\tif indeg[v] == 0 { queue = append(queue, v) }\n\t\t}\n\t}\n\tstatus := int64(0)\n\tif len(order) == n { status = 1 }\n\treturn append([]int64{status}, order...)\n}\n",
